/// <summary>
///    AVA <c>findByRequestID</c> method.
/// </summary>
/// <param name="_worker">
///    <c>HCMWorkerRecId</c> as type
/// </param>
/// <param name="_kcs_KBVRequestID">
///    <c>KCS_KBVRequestID</c> as type
/// </param>
/// <param name="_kcs_KBVInfoArea">
///    <c>KCS_KBVInfoArea</c> as type
/// </param>
/// <param name="_kcs_KBVDataArea">
///    <c>DataAreaId</c> as type
/// </param>
/// <param name="_smmSalesUnitId">
///    <c>smmSalesUnitId</c> as type
/// </param>
/// <param name="_forUpdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVInfoTmp</c> as return value
/// </returns>
static KCS_KBVInfoTmp findByRequestID(  HCMWorkerRecId      _worker,
                                        KCS_KBVRequestID    _kcs_KBVRequestID,
                                        KCS_KBVInfoArea     _kcs_KBVInfoArea,
                                        DataAreaId          _kcs_KBVDataArea,
                                        smmSalesUnitId      _smmSalesUnitId,
                                        boolean             _forUpdate          = false )
{
    KCS_KBVInfoTmp locKCS_KBVInfoTmp;

    if (    _worker
        &&  _kcs_KBVRequestID   )
    {
        if (_forUpdate)
        {
            locKCS_KBVInfoTmp.selectForUpdate(_forUpdate);
        }

        select firstonly locKCS_KBVInfoTmp
        where   locKCS_KBVInfoTmp.AVAWorker         == _worker
            &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea   == _kcs_KBVInfoArea
            &&  locKCS_KBVInfoTmp.NDX_KBVRequestID  == _kcs_KBVRequestID
            &&  locKCS_KBVInfoTmp.KCS_KBVDataArea   == _kcs_KBVDataArea
            &&  locKCS_KBVInfoTmp.smmSalesUnitId    == _smmSalesUnitId;
    }

    return locKCS_KBVInfoTmp;
}

/// <summary>
///    AVA <c>equalizeDataAreas</c> method.
/// </summary>
/// <param name="_worker">
///    <c>HCMWorkerRecId</c> as type
/// </param>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_kcs_KBVInfoArea">
///    <c>KCS_KBVInfoArea</c> as type
/// </param>
/// <param name="_smmSalesUnitId">
///    <c>smmSalesUnitId</c> as type
/// </param>
/// <param name="_kcs_KBVInfoReason">
///    <c>KCS_KBVInfoReason</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public static boolean equalizeDataAreas(HCMWorkerRecId              _worker,
                                        KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                                        KCS_KBVInfoArea             _kcs_KBVInfoArea,
                                        smmSalesUnitId              _smmSalesUnitId,
                                        KCS_KBVInfoReason           _kcs_KBVInfoReason          = '')
{
    boolean             retVal;

    KCS_KBVInfoTmp      locKCS_KBVInfoTmp;
    KCS_KBVDataArea     locKCS_KBVDataArea;
    KCS_KBVDataAreas    locKCS_KBVDataAreas;
    int64               locCount;
    int                 i;

    select count(RecId)
    from    locKCS_KBVInfoTmp
    where   locKCS_KBVInfoTmp.AVAWorker                 == _worker
        &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea           == _kcs_KBVInfoArea
        &&  locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID  == _kcs_KBVBuildingProjectID
        &&  locKCS_KBVInfoTmp.smmSalesUnitId            == _smmSalesUnitId;
    locCount = locKCS_KBVInfoTmp.RecId;
    if(locCount > 1)
    {
        while select locKCS_KBVInfoTmp
        where   locKCS_KBVInfoTmp.AVAWorker                 == _worker
            &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea           == _kcs_KBVInfoArea
            &&  locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID  == _kcs_KBVBuildingProjectID
            &&  locKCS_KBVInfoTmp.smmSalesUnitId            == _smmSalesUnitId
        {
            for (i = 1; i <= conlen(locKCS_KBVInfoTmp.KCS_KBVDataAreas); i++)
            {
                locKCS_KBVDataArea = conpeek(locKCS_KBVInfoTmp.KCS_KBVDataAreas, i);
                if (!confind(locKCS_KBVDataAreas, locKCS_KBVDataArea))
                {
                    locKCS_KBVDataAreas += locKCS_KBVDataArea;
                }
            }
        }

        ttsbegin;
        while select forupdate locKCS_KBVInfoTmp
        where   locKCS_KBVInfoTmp.AVAWorker                 == _worker
            &&  locKCS_KBVInfoTmp.KCS_KBVInfoArea           == _kcs_KBVInfoArea
            &&  locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID  == _kcs_KBVBuildingProjectID
            &&  locKCS_KBVInfoTmp.smmSalesUnitId            == _smmSalesUnitId
        {
            locKCS_KBVInfoTmp.KCS_KBVDataAreas = locKCS_KBVDataAreas;
            if(_kcs_KBVInfoReason)
            {
                locKCS_KBVInfoTmp.KCS_KBVInfoReason = _kcs_KBVInfoReason;
            }
            locKCS_KBVInfoTmp.KCS_KBVDataAreasTxt = AVAKBVBuildingProjectHelper::container2seperatedStr(locKCS_KBVInfoTmp.KCS_KBVDataAreas);
            locKCS_KBVInfoTmp.update();
            retVal = true;
        }
        ttscommit;
    }

    return retVal;
}

/// <summary>
///    AVA <c>notEmpty</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
static boolean notEmpty()
{
    boolean         retVal;

    KCS_KBVInfoTmp  locKCS_KBVInfoTmp;

    select firstonly RecId 
    from locKCS_KBVInfoTmp;

    if(locKCS_KBVInfoTmp.RecId)
    {
        retVal = true;
    }

    return retVal;
}

/// <summary>
///    AVA <c>addKBVInfoTmp</c> method.
/// </summary>
/// <param name="kCS_KBVBuildingProjectId">
///    <c>KCS_KBVBuildingProjectId</c> as type
/// </param>
/// <param name="kcs_MinDate">
///    <c>KCS_KBVCompetenceEndDate</c> as type
/// </param>
/// <param name="kCS_KBVInfoArea">
///    <c>KCS_KBVInfoArea</c> as type
/// </param>
/// <param name="_smmSalesDistrictId">
///    <c>smmSalesDistrictId</c> as type
/// </param>
/// <param name="changeReason">
///    <c>str</c> as type
/// </param>
static void addKBVInfoTmp(  KCS_KBVBuildingProjectId    kCS_KBVBuildingProjectId,
                            KCS_KBVCompetenceEndDate    kcs_MinDate,
                            KCS_KBVInfoArea             kCS_KBVInfoArea,
                            smmSalesDistrictId          _smmSalesDistrictId,
                            str                         changeReason                )
{
    KCS_KBVResponsibilitiesTable    locKCS_KBVResponsibilitiesTable;
    KCS_KBVBuildingProjectTable     locKCS_KBVBuildingProjectTable;
    KCS_KBVInfoTmp                  locKCS_KBVInfoTmp;

    container                       allBPCompanies;

    locKCS_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::find(kCS_KBVBuildingProjectId);
    allBPCompanies = AVAKBVBuildingProjectHelper::getAllBPCompanies();

    while select crosscompany : allBPCompanies locKCS_KBVResponsibilitiesTable
    where   locKCS_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID        == kCS_KBVBuildingProjectId
        &&  (   locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate    == DateNull()
            ||  locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate    >= kcs_MinDate    )
    {
        switch(kCS_KBVInfoArea)
        {
            case KCS_KBVInfoArea::BVChanged:
                select firstonly forupdate locKCS_KBVInfoTmp
                where   locKCS_KBVInfoTmp.AVAWorker                 == locKCS_KBVResponsibilitiesTable.smmWorker
                    &&  (locKCS_KBVInfoTmp.KCS_KBVInfoArea          == KCS_KBVInfoArea::BVChanged || KCS_KBVInfoArea::BVNew)
                    &&  locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID  == kCS_KBVBuildingProjectId;
                break;

            case KCS_KBVInfoArea::QuotationChanged:
                select firstonly forupdate locKCS_KBVInfoTmp
                where   locKCS_KBVInfoTmp.AVAWorker                 == locKCS_KBVResponsibilitiesTable.smmWorker
                    &&  (locKCS_KBVInfoTmp.KCS_KBVInfoArea          == KCS_KBVInfoArea::QuotationChanged || KCS_KBVInfoArea::QuotationNew)
                    &&  locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID  == kCS_KBVBuildingProjectId;
                break;

            default:
                locKCS_KBVInfoTmp = KCS_KBVInfoTmp::find(   locKCS_KBVResponsibilitiesTable.smmWorker,
                                                            kCS_KBVBuildingProjectId,
                                                            kCS_KBVInfoArea,
                                                            locKCS_KBVBuildingProjectTable.dataAreaId,
                                                            _smmSalesDistrictId,
                                                            true                                    );
            /*
            default:
                locKCS_KBVInfoTmp = KCS_KBVInfoTmp::findGlobal( locKCS_KBVResponsibilitiesTable.smmWorker,
                                                                kCS_KBVBuildingProjectId,
                                                                kCS_KBVInfoArea,
                                                                true    );
            */
        }

        ttsbegin;

        if (!locKCS_KBVInfoTmp.recId)
        {
            locKCS_KBVInfoTmp.clear();
            locKCS_KBVInfoTmp.KCS_KBVInfoArea              = kCS_KBVInfoArea;
            locKCS_KBVInfoTmp.KCS_KBVBuildingProjectID     = kCS_KBVBuildingProjectId;
            locKCS_KBVInfoTmp.AVAWorker                    = locKCS_KBVResponsibilitiesTable.smmWorker;
            locKCS_KBVInfoTmp.smmSalesUnitId               = _smmSalesDistrictId;
            locKCS_KBVInfoTmp.KCS_KBVInfoReason            = changeReason;
            locKCS_KBVInfoTmp.KCS_KBVDataArea              = locKCS_KBVBuildingProjectTable.dataAreaId;
            locKCS_KBVInfoTmp.KCS_KBVDataAreas             += locKCS_KBVResponsibilitiesTable.dataAreaId;
            locKCS_KBVInfoTmp.KCS_KBVDataAreasTxt          =  AVAKBVBuildingProjectHelper::container2seperatedStr(locKCS_KBVInfoTmp.KCS_KBVDataAreas);
            locKCS_KBVInfoTmp.insert();
        }
        else
        {
            if (!strscan(locKCS_KBVInfoTmp.KCS_KBVInfoReason, changeReason, 1, strlen(locKCS_KBVInfoTmp.KCS_KBVInfoReason)))
            {
                locKCS_KBVInfoTmp.KCS_KBVInfoReason += changeReason;
            }
            if (!confind(locKCS_KBVInfoTmp.KCS_KBVDataAreas, locKCS_KBVResponsibilitiesTable.dataAreaId))
            {
                locKCS_KBVInfoTmp.KCS_KBVDataAreas += locKCS_KBVResponsibilitiesTable.dataAreaId;
            }
            locKCS_KBVInfoTmp.KCS_KBVDataAreasTxt          =  AVAKBVBuildingProjectHelper::container2seperatedStr(locKCS_KBVInfoTmp.KCS_KBVDataAreas);
            locKCS_KBVInfoTmp.update();
        }
        KCS_KBVInfoTmp::equalizeDataAreas(  locKCS_KBVResponsibilitiesTable.smmWorker,
                                            kCS_KBVBuildingProjectId,
                                            kCS_KBVInfoArea,
                                            locKCS_KBVInfoTmp.KCS_KBVInfoReason,
                                            _smmSalesDistrictId                     );
        ttscommit;
    }
}
